<template>
  <img :src="itemOption.url?itemOption.url:qrBase64" :style="itemStyle">
</template>

<script lang="ts">
import { computed, defineComponent, type StyleValue } from 'vue'
export default defineComponent({
  props: {
    itemOption: {
      type: Object,
      default: () => {
        return {}
      }
    }
  },
  setup (props) {
    const itemStyle = computed((): StyleValue => {
      return {
        width: props.itemOption.component.width + 'px',
        height: props.itemOption.component.height + 'px',
        position: 'absolute',
        top: props.itemOption.component.top + 'px',
        left: props.itemOption.component.left + 'px',
      }
    })
    const qrBase64 = 'data:image/png;base64,'
    return {
      itemStyle,
      qrBase64
    }
  }
})
</script>

